2525: mem_stage_stall_type ldst_unit::process_memory_access_queue_l1cache(
2526:     l1_cache *cache, warp_inst_t &inst) {
2527:   mem_stage_stall_type result = NO_RC_FAIL;
2528:   if (inst.accessq_empty()) return result;
2529: 
2530:   if (m_config->m_L1D_config.l1_latency > 0) {
2531:     auto inst_ptr = std::make_shared<warp_inst_t>(inst);
2532:     for (unsigned int j = 0; j < m_config->m_L1D_config.l1_banks;
2533:          j++) {  // We can handle at max l1_banks reqs per cycle
2534: 
2535:       if (inst.accessq_empty()) return result;
2536: 
2537:       if (!dtc_l1_try_tag(inst.accessq_back().get_addr())) {
2538:         result = BK_CONF;
2539:         break;
2540:       }
2541: 
2542:       mem_fetch *mf =
2543:           m_mf_allocator->alloc(inst_ptr, inst.accessq_back(),
2544:                                 m_core->get_gpu()->gpu_sim_cycle +
2545:                                     m_core->get_gpu()->gpu_tot_sim_cycle);
2546:       unsigned bank_id = m_config->m_L1D_config.set_bank(mf->get_addr());
2547:       assert(bank_id < m_config->m_L1D_config.l1_banks);
2548: 
2549:       if ((l1_latency_queue[bank_id][m_config->m_L1D_config.l1_latency - 1]) ==
2550:           NULL) {
2551:         l1_latency_queue[bank_id][m_config->m_L1D_config.l1_latency - 1] = mf;
2552: 
2553:         if (mf->get_inst().is_store()) {
2554:           unsigned inc_ack =
2555:               (m_config->m_L1D_config.get_mshr_type() == SECTOR_ASSOC)
2556:                   ? (mf->get_data_size() / SECTOR_SIZE)
2557:                   : 1;
2558: 
2559:           for (unsigned i = 0; i < inc_ack; ++i)
2560:             m_core->inc_store_req(inst.warp_id());
2561:         }
2562: 
2563:         inst.accessq_pop_back();
2564:       } else {
2565:         result = BK_CONF;
2566:         m_stats->gpgpu_n_l1cache_bkconflict++;
2567:         delete mf;
2568:         break;  // do not try again, just break from the loop and try the next
2569:                 // cycle
2570:       }
2571:     }
2572:     if (!inst.accessq_empty() && result != BK_CONF) result = COAL_STALL;

2683: bool ldst_unit::dtc_l1_oo_select_ready(uint64_t *uid) const {
2684:   for (auto candidate = m_dtc_l1_oo_pib.begin();
2685:        candidate != m_dtc_l1_oo_pib.end(); ++candidate) {
2686:     if (candidate->operation == dtc_l1_m4_operation::CACHEABLE_LOAD &&
2687:         candidate->next_reference != candidate->references.size())
2688:       continue;
2689:     const uint64_t candidate_uid = candidate->inst.get_uid();
2690:     const bool ready = dtc_l1_sector_oo_active()
2691:                            ? m_dtc_l1_sector_frontend->entry_ready_for(candidate_uid)
2692:                            : m_dtc_l1_oo_frontend->entry_ready_for(candidate_uid);
2693:     if (!ready) continue;
2694:     bool older_same_warp_fence = false;
2695:     for (auto older = m_dtc_l1_oo_pib.begin(); older != candidate; ++older) {
2696:       if (older->inst.warp_id() == candidate->inst.warp_id() &&
2697:           older->operation == dtc_l1_m4_operation::PROXY_FENCE) {
2698:         older_same_warp_fence = true;
2699:         break;
2700:       }
2701:     }
2702:     if (!older_same_warp_fence) {
2703:       if (uid) *uid = candidate_uid;
2704:       return true;
2705:     }
2706:   }
2707:   return false;

