2961: bool ldst_unit::dtc_l1_service_collect(
2962:     dtc_l1::service_entry &service,
2963:     const std::vector<dtc_l1::line_reference> &references) {
2964:   if (!dtc_l1_finite_service_active()) return true;
2965:   const uint64_t cycle = m_core->get_gpu()->global_cycle();
2966:   if (service.ready_cycle == UINT64_MAX) {
2967:     unsigned sectors = 0;
2968:     for (const auto &reference : references)
2969:       sectors += __builtin_popcount(reference.sector_mask);
2970:     service.observe_ready(cycle, sectors);
2971:     if (m_config->dtc_l1_progressive_wakeup) ++m_dtc_progressive_collectable_entries;
2972:   }
2973:   const unsigned before = service.sectors_left;
2974:   const bool collected = service.collect(cycle, m_dtc_service_collect);
2975:   m_dtc_service_collected_sectors += before - service.sectors_left;
2976:   return collected;
2977: }
