2979: void ldst_unit::dtc_l1_service_retired(const dtc_l1::service_entry &service) {
2980:   if (!dtc_l1_finite_service_active()) return;
2981:   const uint64_t cycle = m_core->get_gpu()->global_cycle();
2982:   assert(service.ready_cycle != UINT64_MAX &&
2983:          service.collect_done_cycle != UINT64_MAX && !service.sectors_left);
2984:   m_dtc_service_retire.commit(cycle);
2985:   m_dtc_service_ready_to_complete_sum += cycle - service.ready_cycle;
2986:   m_dtc_service_ready_to_collect_sum += service.collect_start_cycle - service.ready_cycle;
2987:   m_dtc_service_collection_cycles += service.collect_done_cycle - service.collect_start_cycle + 1;
2988:   m_dtc_service_wb_wait += cycle - service.collect_done_cycle - 1;
2989:   if (m_config->dtc_l1_progressive_wakeup) {
2990:     assert(service.admitted_returns_cycle != UINT64_MAX &&
2991:            service.admitted_returns_cycle <= service.ready_cycle);
2992:     m_dtc_progressive_returns_to_retire_sum += cycle - service.admitted_returns_cycle;
2993:   }
2994:   ++m_dtc_service_retired;
2995: }

3286: bool ldst_unit::dtc_l1_oo_memory_cycle(
3287:     warp_inst_t &inst, mem_stage_stall_type &stall_reason,
3288:     mem_stage_access_type &access_type) {
3289:   const unsigned uid = inst.get_uid();
3290:   dtc_l1_oo_pib_entry *entry = dtc_l1_oo_find_entry(uid);
3291:   if (!entry) {
3292:     const bool admitted = dtc_l1_sector_oo_active()
3293:                              ? m_dtc_l1_sector_frontend->admit(uid)
3294:                              : m_dtc_l1_oo_frontend->admit(uid);
3295:     if (!admitted) {
3296:       stall_reason = BK_CONF;
3297:       access_type = G_MEM_LD;
3298:       return false;
3299:     }
3300:     m_dtc_l1_oo_pib.push_back({inst, dtc_l1_io_line_references(inst), 0});
3301:     entry = &m_dtc_l1_oo_pib.back();
3302:     assert(!entry->references.empty());
3303:     dtc_l1_r4c0_record_pib(entry->inst, entry->references, "OO");
3304:   }
3305:   if (entry->next_reference < entry->references.size()) {
3306:     const dtc_l1::line_reference reference =
3307:         entry->references[entry->next_reference];
3308:     const unsigned long long cycle =
3309:         m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle;
3310:     // Modern sector mode can enqueue up to four candidates for one logical
3311:     // reference.  Reserve that maximum before frontend mutation so its
3312:     // bounded candidate queue cannot overflow after allocation.
3313:     const size_t lower_candidate_reservation =
3314:         dtc_l1_sector_oo_active()
3315:             ? m_dtc_l1_sector_frontend->prospective_new_requests(
3316:                   reference.line_address, reference.sector_mask)
3317:             : (m_dtc_l1_oo_frontend->will_new_miss(reference.line_address)
3318:                    ? 1
3319:                    : 0);
3320:     if (m_dtc_l1_oo_lower_create_queue.size() +
3321:             lower_candidate_reservation >
3322:         m_config->dtc_l1_oo_pib_entries) {
3323:       ++m_dtc_l1_oo_lower_create_queue_full_stalls;
3324:       stall_reason = BK_CONF;
3325:       access_type = G_MEM_LD;
3326:       return false;
3327:     }
3328:     const bool prior_grant = dtc_l1_finite_service_active() &&
3329:                             entry->service.tag_grant_cycle != UINT64_MAX;
3330:     const bool tag_served = prior_grant || (dtc_l1_sector_oo_active()
3331:                                 ? m_dtc_l1_sector_frontend->try_serve_tag(
3332:                                       cycle, reference.line_address)
3333:                                 : m_dtc_l1_oo_frontend->try_serve_tag(
3334:                                       cycle, reference.line_address));
3335:     if (!tag_served) {
3336:       stall_reason = BK_CONF;
3337:       access_type = G_MEM_LD;
3338:       return false;
3339:     }
3340:     if (dtc_l1_finite_service_active() &&
3341:         (!prior_grant || !entry->service.tag_can_commit(cycle))) {
3342:       if (!prior_grant) entry->service.tag_grant_cycle = cycle;
3343:       stall_reason = COAL_STALL;
3344:       access_type = G_MEM_LD;
3345:       return false;
3346:     }
3347:     if (dtc_l1_sector_oo_active()) {
3348:       const dtc_l1::sector_oo_frontend::access_result result =
3349:           m_dtc_l1_sector_frontend->access(cycle, uid, reference.line_address,
3350:                                             reference.sector_mask);
3351:       if (result.kind == dtc_l1::io_access_kind::NO_FREE_LINE) {
3352:         stall_reason = BK_CONF;
3353:         access_type = G_MEM_LD;
3354:         return false;
3355:       }
3356:       for (unsigned sector = 0; sector < dtc_l1::kSectorsPerLogicalLine;
3357:            ++sector) {
3358:         const uint8_t sector_bit = static_cast<uint8_t>(1U << sector);
3359:         if (!(result.new_request_mask & sector_bit)) continue;
3360:         assert(m_dtc_l1_oo_lower_create_queue.size() <
3361:                m_config->dtc_l1_oo_pib_entries);
3362:         m_dtc_l1_oo_lower_create_queue.push_back(
3363:             {uid, result.physical, reference.line_address, sector_bit});
3364:       }
3365:     } else {
3366:       const dtc_l1::io_access_result result =
3367:           m_dtc_l1_oo_frontend->access(cycle, uid, reference.line_address);
3368:       if (result.kind == dtc_l1::io_access_kind::NO_FREE_LINE) {
3369:         stall_reason = BK_CONF;
3370:         access_type = G_MEM_LD;
3371:         return false;
3372:       }
3373:       if (result.kind == dtc_l1::io_access_kind::NEW_MISS) {
3374:         assert(m_dtc_l1_oo_lower_create_queue.size() <
3375:                m_config->dtc_l1_oo_pib_entries);
3376:         m_dtc_l1_oo_lower_create_queue.push_back(
3377:             {uid, result.physical, reference.line_address, 0xF});
3378:       }
3379:     }
3380:     ++entry->next_reference;
3381:     if (dtc_l1_finite_service_active()) {
3382:       const bool has_next = entry->next_reference < entry->references.size();
3383:       entry->service.prefetch_next_tag(*m_dtc_l1_oo_frontend, cycle, has_next,
3384:           has_next ? entry->references[entry->next_reference].line_address : 0);
3385:     }
3386:   }
3387:   if (entry->next_reference != entry->references.size()) {
3388:     stall_reason = COAL_STALL;
3389:     access_type = G_MEM_LD;
3390:     return false;
3391:   }
3392:   while (!inst.accessq_empty()) inst.accessq_pop_back();
3393:   return true;
3394: }

3396: void ldst_unit::dtc_l1_oo_issue_lower_requests() {
3397:   if (!dtc_l1_paper_oo_active()) return;
3398:   const unsigned long long cycle =
3399:       m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle;
3400:   if (!m_dtc_l1_oo_lower_create_queue.empty() &&
3401:       (!dtc_l1_finite_service_active() || m_dtc_service_create.available(cycle)) &&
3402:       m_core->get_gpu()->dtc_l1_try_acquire_lower_request()) {
3403:     if (dtc_l1_finite_service_active()) m_dtc_service_create.commit(cycle);
3404:     const dtc_l1_oo_lower_candidate candidate =
3405:         m_dtc_l1_oo_lower_create_queue.front();
3406:     dtc_l1_oo_pib_entry *entry = dtc_l1_oo_find_entry(candidate.inst_uid);
3407:     assert(entry);
3408:     mem_access_byte_mask_t byte_mask;
3409:     mem_access_sector_mask_t sector_mask;
3410:     uint64_t request_address = candidate.line_address;
3411:     unsigned request_size = dtc_l1::kLogicalLineBytes;
3412:     if (dtc_l1_sector_oo_active()) {
3413:       assert(candidate.sector_mask && !(candidate.sector_mask &
3414:                                          (candidate.sector_mask - 1)) &&
3415:              !(candidate.sector_mask & ~0xFU));
3416:       unsigned sector = 0;
3417:       while (!(candidate.sector_mask & (1U << sector))) ++sector;
3418:       request_address += sector * 32;
3419:       request_size = 32;
3420:       sector_mask.set(sector);
3421:       for (unsigned byte = sector * 32; byte < (sector + 1) * 32; ++byte)
3422:         byte_mask.set(byte);
3423:     } else {
3424:       byte_mask.set();
3425:       sector_mask.set();
3426:     }
3427:     mem_access_t lower_read(GLOBAL_ACC_R, request_address, request_size, false,
3428:                             entry->inst.get_warp_active_mask(), byte_mask,
3429:                             sector_mask, m_memory_config->gpgpu_ctx);
3430:     mem_fetch *mf = m_mf_allocator->alloc(entry->inst, lower_read, cycle);
3431:     const bool inserted = m_dtc_l1_oo_inflight
3432:                               .emplace(mf->get_request_uid(),
3433:                                        dtc_l1_oo_inflight{candidate.physical,
3434:                                                            candidate.line_address,
3435:                                                            candidate.inst_uid,
3436:                                                            candidate.sector_mask})
3437:                               .second;
3438:     assert(inserted && "OO request UID must remain unique while live");
3439:     m_dtc_l1_oo_lower_issue_queue.push_back(mf);
3440:     m_dtc_l1_oo_lower_create_queue.pop_front();
3441:     ++m_dtc_l1_oo_lower_created;
3442:   }
3443:   // Frozen lower issue width: one request per SM/cycle.
3444:   if (!m_dtc_l1_oo_lower_issue_queue.empty()) {
3445:     mem_fetch *mf = m_dtc_l1_oo_lower_issue_queue.front();
3446:     if ((!dtc_l1_finite_service_active() || m_dtc_service_inject.available(cycle)) &&
3447:         !m_icnt->full(mf->size(), false)) {
3448:       if (dtc_l1_finite_service_active()) m_dtc_service_inject.commit(cycle);
3449:       mf->set_status(IN_ICNT_TO_MEM, cycle);
3450:       m_icnt->push(mf);
3451:       m_dtc_l1_oo_lower_issue_queue.pop_front();
3452:       ++m_dtc_l1_oo_lower_issued;
3453:     }
3454:   }

3529: bool ldst_unit::dtc_l1_oo_writeback_ready() {
3530:   const uint64_t service_cycle = m_core->get_gpu()->global_cycle();
3531:   if (dtc_l1_finite_service_active() &&
3532:       !m_dtc_service_retire.available(service_cycle)) return false;
3533:   if (!dtc_l1_paper_oo_active()) return false;
3534:   uint64_t uid = 0;
3535:   const bool ready = dtc_l1_oo_select_ready(&uid);
3536:   if (!ready) return false;
3537:   dtc_l1_oo_pib_entry *entry = dtc_l1_oo_find_entry(static_cast<unsigned>(uid));
3538:   assert(entry);
3539:   const unsigned long long cycle =
3540:       m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle;
3541:   if (entry->operation != dtc_l1_m4_operation::CACHEABLE_LOAD) {
3542:     assert(entry->source_completed && entry->references.empty());
3543:     const bool retired_ok = dtc_l1_sector_oo_active()
3544:                                 ? m_dtc_l1_sector_frontend->retire_ready_uid(
3545:                                       cycle, uid)
3546:                                 : m_dtc_l1_oo_frontend->retire_ready_uid(cycle,
3547:                                                                          uid);
3548:     assert(retired_ok);
3549:     if (dtc_l1_finite_service_active()) m_dtc_service_retire.commit(service_cycle);
3550:     for (auto it = m_dtc_l1_oo_pib.begin(); it != m_dtc_l1_oo_pib.end(); ++it)
3551:       if (it->inst.get_uid() == uid) {
3552:         m_dtc_l1_oo_pib.erase(it);
3553:         break;
3554:       }
3555:     ++m_dtc_l1_m4_observation_retires;
3556:     m_dtc_l1_oo_out_of_order_retires =
3557:         dtc_l1_sector_oo_active()
3558:             ? m_dtc_l1_sector_frontend->out_of_order_retires()
3559:             : m_dtc_l1_oo_frontend->out_of_order_retires();
3560:     return true;
3561:   }
3562:   if (!dtc_l1_service_collect(entry->service, entry->references)) return false;
3563:   m_next_wb = entry->inst;
3564:   if (!m_operand_collector->writeback(m_next_wb)) {
3565:     ++m_dtc_l1_oo_ready_but_wb_blocked_cycles;
3566:     m_next_wb.clear();
3567:     return false;
3568:   }
3569:   // Mirror IO: readiness becomes a non-retryable ledger transition only on
3570:   // the successful shared-operand-collector grant.
3571:   dtc_l1_r4c1_record_ready(entry->inst,
3572:                             static_cast<unsigned>(entry->next_reference),
3573:                             static_cast<unsigned>(entry->references.size()), "OO");
3574:   const unsigned dependencies =
3575:       dtc_l1_r4c3_registered_dependencies(entry->inst);
3576:   dtc_l1_service_retired(entry->service);
3577:   dtc_l1_oo_complete_instruction(entry->inst, dependencies);
3578:   uint64_t retired = 0;
3579:   const bool retired_ok = dtc_l1_sector_oo_active()
3580:                               ? m_dtc_l1_sector_frontend->retire_ready_uid(
3581:                                     cycle, uid)
3582:                               : m_dtc_l1_oo_frontend->retire_ready_uid(cycle,
3583:                                                                        uid);
3584:   assert(retired_ok);
3585:   for (auto it = m_dtc_l1_oo_pib.begin(); it != m_dtc_l1_oo_pib.end(); ++it) {
3586:     if (it->inst.get_uid() == uid) {
3587:       m_dtc_l1_oo_pib.erase(it);
3588:       break;
3589:     }
3590:   }
3591:   m_dtc_l1_oo_out_of_order_retires =
3592:       dtc_l1_sector_oo_active()
3593:           ? m_dtc_l1_sector_frontend->out_of_order_retires()
3594:           : m_dtc_l1_oo_frontend->out_of_order_retires();
3595:   m_next_wb.clear();
3596:   return true;

3738: void ldst_unit::L1_latency_queue_cycle() {
3739:   for (unsigned int j = 0; j < m_config->m_L1D_config.l1_banks; j++) {
3740:     if ((l1_latency_queue[j][0]) != NULL) {
3741:       mem_fetch *mf_next = l1_latency_queue[j][0];
3742:       std::list<cache_event> events;
3743:       enum cache_request_status status =
3744:           m_L1D->access(mf_next->get_addr(), mf_next,
3745:                         m_core->get_gpu()->gpu_sim_cycle +
3746:                             m_core->get_gpu()->gpu_tot_sim_cycle,
3747:                         events);
3748:       dtc_l1_debug_event("L1_ACCESS", mf_next->get_inst(),
3749:                          mf_next->get_addr(), cache_request_status_str(status));
3750:       dtc_l1_io_identity_event("ISSUE_L1_ACCESS", *mf_next);
3751: 
3752:       bool write_sent = was_write_sent(events);
3753:       bool read_sent = was_read_sent(events);
3754: 
3755:       if (status == HIT) {
3756:         assert(!read_sent);
3757:         l1_latency_queue[j][0] = NULL;
3758:         if (mf_next->get_inst().is_load()) {
3759:           for (unsigned r = 0; r < MAX_OUTPUT_VALUES; r++)
3760:             if (mf_next->get_inst().out[r] > 0) {
3761:               assert(m_pending_writes[mf_next->get_inst().warp_id()]
3762:                                      [mf_next->get_inst().out[r]] > 0);
3763:               const unsigned before =
3764:                   m_pending_writes[mf_next->get_inst().warp_id()]
3765:                                   [mf_next->get_inst().out[r]];
3766:               unsigned still_pending =
3767:                   --m_pending_writes[mf_next->get_inst().warp_id()]
3768:                                     [mf_next->get_inst().out[r]];
3769:               dtc_l1_r4c2_trace_pending_mutation(
3770:                   mf_next->get_inst(), mf_next->get_inst().out[r], before, -1,
3771:                   still_pending, "CONVENTIONAL_L1_LATENCY_HIT");
3772:               if (!still_pending) {
3773:                 m_pending_writes[mf_next->get_inst().warp_id()].erase(
3774:                     mf_next->get_inst().out[r]);
3775:                 m_scoreboard->releaseRegister(mf_next->get_inst().warp_id(),
3776:                                               mf_next->get_inst().out[r]);
3777:                 m_core->warp_inst_complete(mf_next->get_inst());
3778:                 dtc_l1_retire(mf_next->get_inst());
3779:                 dtc_l1_debug_event("HIT_TRUE_COMPLETE_RETIRED",
3780:                                    mf_next->get_inst(), mf_next->get_addr(),
3781:                                    "HIT");
3782:               }
3783:             }
3784: 
3785:           // release LDGSTS
3786:           if (mf_next->get_inst().m_is_ldgsts) {
3787:             m_pending_ldgsts[mf_next->get_inst().warp_id()]
3788:                             [mf_next->get_inst().get_uid()]--;
3789:             if (m_pending_ldgsts[mf_next->get_inst().warp_id()]
3790:                                 [mf_next->get_inst().get_uid()] == 0) {
3791:               // This LDGSTS instruction is done, we remove it
3792:               // from the pending LDGSTS map and unset the DEPBAR
