78: struct service_entry {
79:   // AD common boundary: first LDST observation with admission complete and
80:   // all real whole-line returns accepted. Independent of notification gating.
81:   uint64_t admitted_returns_cycle = UINT64_MAX;
82:   uint64_t tag_grant_cycle = UINT64_MAX;
83:   uint64_t ready_cycle = UINT64_MAX;
84:   uint64_t collect_done_cycle = UINT64_MAX;
85:   uint64_t collect_start_cycle = UINT64_MAX;
86:   unsigned sectors_left = 0;
87:   bool tag_can_commit(uint64_t cycle) const {
88:     return tag_grant_cycle != UINT64_MAX && cycle > tag_grant_cycle;
89:   }
90:   template <class Frontend>
91:   void prefetch_next_tag(Frontend &frontend, uint64_t cycle, bool has_next,
92:                          uint64_t next_address) {
93:     tag_grant_cycle = UINT64_MAX;
94:     if (has_next && frontend.try_serve_tag(cycle, next_address))
95:       tag_grant_cycle = cycle;
96:   }
97:   void observe_ready(uint64_t cycle, unsigned sectors) {
98:     assert(ready_cycle == UINT64_MAX && sectors);
99:     ready_cycle = cycle;
100:     sectors_left = sectors;
101:   }
102:   bool collect(uint64_t cycle, service_quota &port) {
103:     assert(ready_cycle != UINT64_MAX);
104:     if (cycle == ready_cycle) return false;
105:     while (sectors_left && port.available(cycle)) {
106:       if (collect_start_cycle == UINT64_MAX) collect_start_cycle = cycle;
107:       port.commit(cycle);
108:       --sectors_left;
109:       if (!sectors_left) collect_done_cycle = cycle;
110:     }
111:     return !sectors_left && cycle > collect_done_cycle;
112:   }
113: };

