713:     assert(!physical.ready && "OO fill must wake each waiter exactly once");
714:     if (m_cfg.finite_service) {
715:       assert(m_service_cycle != UINT64_MAX);
716:       for (const auto &pending : m_service_returns)
717:         assert(pending.physical.id != identity.id ||
718:                pending.physical.generation != identity.generation);
719:       if (m_cfg.progressive_wakeup) physical.return_cycle = m_service_cycle;
720:       m_service_returns.push_back({identity, m_service_cycle + 1, 0});
721:       return;
722:     }
723:     physical.ready = true;
724:     for (const waiter &waiting : physical.waiters) {
725:       entry *owner = find_entry_by_slot(waiting.slot, waiting.slot_generation);
726:       assert(owner && has_reference(*owner, identity) &&
727:              "stale fill cannot wake a reused OO PIB slot");
728:       assert(owner->pending_dependencies);
