580: /// Checks if there is space for tracking a new memory access
581: bool mshr_table::full(new_addr_type block_addr) const {
582:   table::const_iterator i = m_data.find(block_addr);
583:   if (i != m_data.end())
584:     return i->second.m_list.size() >= m_max_merged;
585:   else
586:     return m_data.size() >= m_num_entries;
587: }
