589: /// Add or merge this access
590: void mshr_table::add(new_addr_type block_addr, mem_fetch *mf) {
591:   m_data[block_addr].m_list.push_back(mf);
592:   assert(m_data.size() <= m_num_entries);
593:   assert(m_data[block_addr].m_list.size() <= m_max_merged);
594:   // indicate that this MSHR entry contains an atomic operation
595:   if (mf->isatomic()) {
596:     m_data[block_addr].m_has_atomic = true;
597:   }
598: }
