600: /// check is_read_after_write_pending
601: bool mshr_table::is_read_after_write_pending(new_addr_type block_addr) {
602:   std::list<mem_fetch *> my_list = m_data[block_addr].m_list;
603:   bool write_found = false;
604:   for (std::list<mem_fetch *>::iterator it = my_list.begin();
605:        it != my_list.end(); ++it) {
606:     if ((*it)->is_write())  // Pending Write Request
607:       write_found = true;
608:     else if (write_found)  // Pending Read Request and we found previous Write
609:       return true;
610:   }
611: 
612:   return false;
613: }
