615: /// Accept a new cache fill response: mark entry ready for processing
616: void mshr_table::mark_ready(new_addr_type block_addr, bool &has_atomic) {
617:   assert(!busy());
618:   table::iterator a = m_data.find(block_addr);
619:   assert(a != m_data.end());
620:   m_current_response.push_back(block_addr);
621:   has_atomic = a->second.m_has_atomic;
622:   assert(m_current_response.size() <= m_data.size());
623: }
624: 
625: /// Returns next ready access
626: mem_fetch *mshr_table::next_access() {
627:   assert(access_ready());
628:   new_addr_type block_addr = m_current_response.front();
629:   assert(!m_data[block_addr].m_list.empty());
630:   mem_fetch *result = m_data[block_addr].m_list.front();
631:   m_data[block_addr].m_list.pop_front();
632:   if (m_data[block_addr].m_list.empty()) {
633:     // release entry
634:     m_data.erase(block_addr);
635:     m_current_response.pop_front();
636:   }
637:   return result;

